    // Independent 35-byte V2 fixture: count; position and velocity signed int24 values
    // scaled by 32; signed int16 angles; three low-32-bit masks; MoveType.
    private static byte[] CompactPayload => Convert.FromHexString(
        "01000000" +
        "280000B0FFFF780000" +
        "FCEFFF100800010000" +
        "900198E9" +
        "FFFFFFFF0100009002000048" +
