    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void ReadsHistoricalV1FixturesThroughBothReaders(bool compressed)
    {
        var bytes = compressed
            ? Convert.FromBase64String(LegacyCompressedFile)
            : Wrap(Header(1), Convert.FromBase64String(LegacyPayload));

        AssertFrame(Decode(bytes), LegacyFrame(), 1);

        var path = TempPath();
        try
        {
            File.WriteAllBytes(path, bytes);
            using var decompressor = new Decompressor();
            var loaded = ReplayShared.LoadReplayFromPath(path, 2, 3, 4, decompressor, NullLogger.Instance);
            Assert.True(loaded.HasValue);
            AssertFrame(loaded.Value, LegacyFrame(), 1);
        }
        finally
        {
            File.Delete(path);
        }
    }

