    [Fact]
    public void CompactEncodingMatchesIndependentWireFixture()
    {
        var bytes = ReplayShared.SerializeReplay(Header(1), [CompactFrame()]);
        using var decompressor = new Decompressor();
        var raw = decompressor.Unwrap(Payload(bytes)).ToArray();

        using var header = JsonDocument.Parse(bytes.AsMemory(0, Array.IndexOf(bytes, (byte)'\n')));
        Assert.False(header.RootElement.TryGetProperty("FrameSize", out _));
        Assert.Equal(CompactPayload, raw);
        AssertFrame(Decode(Wrap(Header(1) with { Version = 2 }, CompactPayload)), CompactFrame(), 2);
    }

