    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    public void V2KeepsLowBitsAndDiscardsHighBitsInEachButtonField(int field)
    {
        for (var bit = 0; bit < 64; bit++)
        {
            var buttons = (UserCommandButtons)(1UL << bit);
            var frame = CompactFrame() with
            {
                PressedButtons = field == 0 ? buttons : UserCommandButtons.Attack,
                ChangedButtons = field == 1 ? buttons : UserCommandButtons.Jump,
                ScrollButtons = field == 2 ? buttons : UserCommandButtons.Duck,
            };

            // All low bits keep their original positions; high bits never select V1.
            var bytes = ReplayShared.SerializeReplay(Header(1), [frame]);
            AssertFrame(Decode(bytes), LowButtons(frame), 2);
        }
    }

    [Fact]
    public void AllCurrentlyDefinedButtonsAndTheirCombinationUseCompactFormat()
    {
        var buttons = Enum.GetValues<UserCommandButtons>();
        var all = buttons.Aggregate((UserCommandButtons)0, (current, next) => current | next);
        var frames = buttons.Append(all)
            .Select(value => CompactFrame() with
            {
                PressedButtons = value,
                ChangedButtons = all ^ value,
                ScrollButtons = all,
            })
            .ToArray();

        var loaded = Decode(ReplayShared.SerializeReplay(Header(frames.Length), frames));
        Assert.Equal(2, loaded.Content.Header.Version);
        Assert.Equal(frames.Select(LowButtons), loaded.Content.Frames);
    }

    [Fact]
    public void MixedHighButtonsAreDiscardedWithoutRemappingOrChangingInput()
    {
        var original = CompactFrameWithHighButtons();
        var frames = new[] { original };
        var bytes = ReplayShared.SerializeReplay(Header(1), frames);
        using var decompressor = new Decompressor();

        Assert.Equal(CompactPayload, decompressor.Unwrap(Payload(bytes)).ToArray());
        AssertFrame(Decode(bytes), CompactFrame(), 2);
        Assert.Equal(original, frames[0]);
    }

    [Theory]
    [InlineData(0, 0, false)]
    [InlineData(0, 0, true)]
    [InlineData(3, 0, false)]
    [InlineData(3, 0, true)]
    [InlineData(3, 2, false)]
    [InlineData(3, 2, true)]
    public async Task FileWritesRoundTripBothFormatsAndCompressionModes(int level, int workers, bool fullWidth)
    {
        var frames = new List<ReplayFrameData> { CompactFrame(), CompactFrame(), CompactFrame() };
        // A late spatial overflow selects V1; high buttons alone must stay in V2.
        frames[^1] = fullWidth ? V1FallbackFrame() : CompactFrameWithHighButtons();
        var original = frames.ToArray();
        var expected = fullWidth ? original : frames.Select(LowButtons).ToArray();

        var header = Header(frames.Count) with { Version = 99, PreFrame = 1, PostFrame = 2, StageTicks = [1, 2] };
        var expectedVersion = fullWidth ? 1 : 2;
        var path = TempPath();
        try
        {
            Assert.True(await ReplayShared.WriteReplayToFileAsync(header, path, frames, level, workers, NullLogger.Instance));
            var bytes = File.ReadAllBytes(path);
            var loaded = Decode(bytes);
            Assert.Equal(expectedVersion, loaded.Content.Header.Version);
            Assert.Equal(expected, loaded.Content.Frames);
            Assert.Equal(header.StageTicks, loaded.Content.Header.StageTicks);
            Assert.Equal(header.PreFrame, loaded.Content.Header.PreFrame);
            Assert.Equal(header.PostFrame, loaded.Content.Header.PostFrame);
            Assert.Equal(99, header.Version);

            using var decompressor = new Decompressor();
            var fromDisk = ReplayShared.LoadReplayFromPath(path, 2, 3, 4, decompressor, NullLogger.Instance);
            Assert.True(fromDisk.HasValue);
            Assert.Equal(expected, fromDisk.Value.Content.Frames);
            Assert.Equal(original, frames);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void PreservesExistingSpatialQuantizationWithoutMutatingInput(bool fullWidth)
    {
        var original = (fullWidth ? V1FallbackFrame() : CompactFrame()) with
        {
            Origin = new Vector(1.01f, -2.01f, 3.03f),
            Angles = new Vector2D(fullWidth ? 2000.01f : 12.01f, -179.01f),
            Velocity = new Vector(-128.01f, 64.03f, 0.01f),
        };
        var frames = new[] { original };
        var header = Header(1);
        var expected = original with
        {
            Origin = new Vector(1f, -2f, 3.03125f),
            Angles = new Vector2D(fullWidth ? 2000f : 12f, -179f),
            Velocity = new Vector(-128f, 64.03125f, 0f),
        };

        AssertFrame(Decode(ReplayShared.SerializeReplay(header, frames)), expected, fullWidth ? 1 : 2);
        Assert.Equal(original, frames[0]);
        Assert.Equal(1, header.Version);
    }

    [Fact]
    public void CompactFramesUse35BytesInsteadOf64WithoutChangingRuntimeLayout()
    {
        var frames = Enumerable.Repeat(CompactFrame(), 100).ToArray();
        var bytes = ReplayShared.SerializeReplay(Header(frames.Length), frames);
        using var decompressor = new Decompressor();
        var payload = decompressor.Unwrap(Payload(bytes)).ToArray();

        Assert.Equal(64, Unsafe.SizeOf<ReplayFrameData>());
        Assert.Equal(4 + 100 * 64, MemoryPackSerializer.Serialize(frames).Length);
        Assert.Equal(4 + 100 * 35, payload.Length);
    }

    [Theory]
