    public void SignedFixedPointEndpointsRoundTripForEveryComponent(int component)
    {
        var minimum = component < 6 ? -262144f : -1024f;
        var maximum = component < 6 ? 262143.96875f : 1023.96875f;
        var frames = new[] { minimum, -1f / 32f, 0f, 1f / 32f, maximum }
            .Select(value => WithComponent(CompactFrame(), component, value))
            .ToArray();

        var loaded = Decode(ReplayShared.SerializeReplay(Header(frames.Length), frames));
        Assert.Equal(2, loaded.Content.Header.Version);
        Assert.Equal(frames, loaded.Content.Frames.ToArray());
    }

    [Theory]
    [InlineData(0)]
