    [InlineData(3)]
    [InlineData(4)]
    [InlineData(5)]
    [InlineData(6)]
    [InlineData(7)]
    public void SpatialOverflowInAnyComponentFallsBackWithoutClamping(int component)
    {
        var belowMinimum = component < 6 ? -262144.03125f : -1024.03125f;
        var aboveMaximum = component < 6 ? 262144f : 1024f;
        foreach (var value in new[] { belowMinimum, aboveMaximum })
        {
            var frames = new[] { CompactFrame(), WithComponent(CompactFrame(), component, value) };
            var loaded = Decode(ReplayShared.SerializeReplay(Header(frames.Length), frames));
            Assert.Equal(1, loaded.Content.Header.Version);
            Assert.Equal(frames, loaded.Content.Frames.ToArray());
        }
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    [InlineData(4)]
    [InlineData(5)]
    [InlineData(6)]
    [InlineData(7)]
    public void NonFiniteAndExtremeValuesFallBackWithoutOverflowOrBitLoss(int component)
    {
        var values = new[]
        {
            float.MaxValue, float.MinValue, float.PositiveInfinity, float.NegativeInfinity,
            BitConverter.Int32BitsToSingle(0x7FC12345),
        };
        foreach (var value in values)
        {
            var frame = WithComponent(CompactFrame(), component, value);
            var loaded = Decode(ReplayShared.SerializeReplay(Header(1), [frame]));
            Assert.Equal(1, loaded.Content.Header.Version);
            var actual = Assert.Single(loaded.Content.Frames);
            // ModSharp vector equality uses a numeric tolerance and is not reflexive for infinity.
            // Compare every scalar's raw bits to verify the stronger storage guarantee instead.
            for (var scalar = 0; scalar < 8; scalar++)
                Assert.Equal(BitConverter.SingleToInt32Bits(GetComponent(frame, scalar)),
                             BitConverter.SingleToInt32Bits(GetComponent(actual, scalar)));
            Assert.Equal(frame.PressedButtons, actual.PressedButtons);
            Assert.Equal(frame.ChangedButtons, actual.ChangedButtons);
            Assert.Equal(frame.ScrollButtons, actual.ScrollButtons);
            Assert.Equal(frame.MoveType, actual.MoveType);
        }
    }

