    [Fact]
    public void ManyDistinctFramesKeepTheExistingQuantizationAndFieldOrder()
    {
        var random = new Random(12531);
        var frames = new ReplayFrameData[2048];
        var expected = new ReplayFrameData[frames.Length];
        for (var i = 0; i < frames.Length; i++)
        {
            var frame = CompactFrame() with { MoveType = (MoveType)(i & 0xFF) };
            var rounded = frame;
            for (var component = 0; component < 8; component++)
            {
                var range = component < 6 ? 200000f : 180f;
                var value = (random.NextSingle() * 2f - 1f) * range;
                frame = WithComponent(frame, component, value);
                // Reference the pre-existing float quantization rather than the new integer codec.
                rounded = WithComponent(rounded, component, MathF.Round(value * 32f) / 32f);
            }
            frames[i] = frame;
            expected[i] = rounded;
        }

        var loaded = Decode(ReplayShared.SerializeReplay(Header(frames.Length), frames));
        Assert.Equal(2, loaded.Content.Header.Version);
        Assert.Equal(expected, loaded.Content.Frames.ToArray());
    }

