    [Fact]
    public void RejectsWrongVersionTruncationTrailingBytesAndImpossibleCounts()
    {
        var compactHeader = Header(1) with { Version = 2 };
        Assert.Null(ReplayShared.DeserializeReplay(Wrap(compactHeader, Convert.FromBase64String(LegacyPayload)), 0, 0, 0, NullLogger.Instance));
        Assert.Null(ReplayShared.DeserializeReplay(Wrap(Header(1), CompactPayload), 0, 0, 0, NullLogger.Instance));

        for (var length = 0; length < CompactPayload.Length; length++)
            Assert.Null(ReplayShared.DeserializeReplay(Wrap(compactHeader, CompactPayload[..length]), 0, 0, 0, NullLogger.Instance));

        foreach (var invalid in new[]
        {
            CompactPayload.Concat(new byte[] { 0 }).ToArray(),
            CompactPayload.Concat(new byte[10]).ToArray(), // V2 requires exactly 35 bytes per frame
            Convert.FromHexString("FFFFFF7F"), // int.MaxValue frames without data
            Convert.FromHexString("FEFFFFFF"), // invalid negative count
            Convert.FromHexString("FFFFFFFF"), // null frame collection
        })
        {
            Assert.Null(ReplayShared.DeserializeReplay(Wrap(compactHeader, invalid), 0, 0, 0, NullLogger.Instance));
        }
    }

