    [Theory]
    [InlineData(1, 64)]
    [InlineData(2, 35)]
    public void DirectDecoderAllocatesOnlyTheFinalArrayAndDoesNotRetainInput(int version, int frameSize)
    {
        const int count = 8192;
        var fixture = version == 1 ? Convert.FromBase64String(LegacyPayload) : CompactPayload;
        var payload = new byte[sizeof(int) + count * frameSize];
        BinaryPrimitives.WriteInt32LittleEndian(payload, count);
        for (var i = 0; i < count; i++)
            fixture.AsSpan(sizeof(int)).CopyTo(payload.AsSpan(sizeof(int) + i * frameSize));

        _ = ReplayFrameStorage.Deserialize(payload, version);
        var before = GC.GetAllocatedBytesForCurrentThread();
        var frames = ReplayFrameStorage.Deserialize(payload, version)!;
        var allocated = GC.GetAllocatedBytesForCurrentThread() - before;

        // No intermediate array proportional to the frame count may be allocated.
        Assert.InRange(allocated, count * 64L, count * 64L + 1024);
        Array.Fill(payload, (byte)0xCC);
        var expected = version == 1 ? LegacyFrame() : CompactFrame();
        Assert.Equal(count, frames.Length);
        Assert.All(frames, frame => Assert.Equal(expected, frame));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void EncodingIntoCallerBufferDoesNotAllocateAnIntermediateFrameArray(bool fullWidth)
    {
        var frames = Enumerable.Repeat(fullWidth ? V1FallbackFrame() : CompactFrame(), 8192).ToArray();
        var output = new byte[sizeof(int) + frames.Length * (fullWidth ? 64 : 35)];
        for (var i = 0; i < 4; i++)
            new ReplayFrameStorage(frames).Serialize(output);

        var before = GC.GetAllocatedBytesForCurrentThread();
        var storage = new ReplayFrameStorage(frames);
        storage.Serialize(output);
        var allocated = GC.GetAllocatedBytesForCurrentThread() - before;

        // Allow bounded runtime/test-runner initialization, far below one full frame array.
        Assert.InRange(allocated, 0, 16 * 1024);
        Assert.Equal(frames, ReplayFrameStorage.Deserialize(output, storage.Version));
        if (fullWidth)
            Assert.Equal(MemoryPackSerializer.Serialize(frames), output);
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(1, false)]
    [InlineData(1872, false)]
    [InlineData(1873, false)]
    [InlineData(8192, false)]
    [InlineData(1, true)]
    [InlineData(1023, true)]
    [InlineData(1024, true)]
    [InlineData(8192, true)]
    public async Task AsyncEncoderWritesBoundedChunksWithExactlyOneArrayHeader(int count, bool fullWidth)
    {
        var frames = Enumerable.Range(0, count)
            .Select(i => (fullWidth ? V1FallbackFrame() : CompactFrame()) with
            {
                Origin = new Vector(i / 32f, -i / 32f, (i % 100) / 32f),
            }).ToArray();
        var storage = new ReplayFrameStorage(frames);
        await using var stream = new DelayedRecordingStream();
        await storage.SerializeAsync(stream);
        var payload = stream.ToArray();

        Assert.InRange(stream.LargestWrite, 4, 64 * 1024);
        Assert.Equal(sizeof(int) + count * storage.FrameSize, payload.Length);
        Assert.Equal(count, BinaryPrimitives.ReadInt32LittleEndian(payload));
        Assert.Equal(frames, ReplayFrameStorage.Deserialize(payload, storage.Version));
        if (fullWidth)
            Assert.Equal(MemoryPackSerializer.Serialize(frames), payload);
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(0, true)]
    [InlineData(3, false)]
    [InlineData(3, true)]
    public async Task LargeFilesAndHeadersRoundTripWithoutRetainingPooledBuffers(int level, bool fullWidth)
    {
        var frames = Enumerable.Range(0, 8192)
            .Select(i => (fullWidth ? V1FallbackFrame() : CompactFrame()) with
            {
                Origin = new Vector(i / 32f, -i / 32f, i % 16),
            }).ToArray();
        var header = Header(frames.Length) with { StageTicks = Enumerable.Range(0, 2048).ToList() };
        var firstPath = TempPath();
        var secondPath = TempPath();
        try
        {
            Assert.True(await ReplayShared.WriteReplayToFileAsync(header, firstPath, frames, level, 0, NullLogger.Instance));
            var bytes = File.ReadAllBytes(firstPath);
            Assert.True(Array.IndexOf(bytes, (byte)'\n') > 4096);
            var memoryLoaded = Decode(bytes);
            using var decompressor = new Decompressor();
            var diskLoaded = ReplayShared.LoadReplayFromPath(firstPath, 2, 3, 4, decompressor, NullLogger.Instance);
            Assert.True(diskLoaded.HasValue);

            // Load different contents of the same size to exercise reuse of both byte pools.
            var replacement = Enumerable.Repeat(fullWidth ? V1FallbackFrame() : CompactFrame(), frames.Length).ToArray();
            Assert.True(await ReplayShared.WriteReplayToFileAsync(header, secondPath, replacement, level, 0, NullLogger.Instance));
            _ = Decode(File.ReadAllBytes(secondPath));
            var second = ReplayShared.LoadReplayFromPath(secondPath, 2, 3, 4, decompressor, NullLogger.Instance);
            Assert.True(second.HasValue);
            Assert.Equal(replacement, second.Value.Content.Frames);

            Array.Fill(bytes, (byte)0xCC);
            Assert.Equal(frames, memoryLoaded.Content.Frames);
            Assert.Equal(frames, diskLoaded.Value.Content.Frames);
            Assert.Equal(header.StageTicks, diskLoaded.Value.Content.Header.StageTicks);
        }
        finally
        {
            File.Delete(firstPath);
            File.Delete(secondPath);
        }
    }

    [Fact]
    public void UploadResultOwnsItsBufferAcrossSubsequentSaves()
    {
        var frames = Enumerable.Repeat(CompactFrame(), 8192).ToArray();
        var first = ReplayShared.SerializeReplay(Header(frames.Length), frames);
        var savedBytes = first.ToArray();
        Array.Fill(frames, CompactFrame() with { Origin = new Vector(12, 34, 56) });
        _ = ReplayShared.SerializeReplay(Header(frames.Length), frames);

        Assert.Equal(savedBytes, first);
        Assert.All(Decode(first).Content.Frames, frame => Assert.Equal(CompactFrame(), frame));
    }

    [Fact]
    public void PooledFileReaderClosesHandleBeforeBackingUpCorruptFiles()
    {
        var path = TempPath();
        var invalid = new byte[] { 1, 2, 3, 4, 5 };
        try
        {
            File.WriteAllBytes(path, invalid);
            using var decompressor = new Decompressor();
            Assert.Null(ReplayShared.LoadReplayFromPath(path, 2, 3, 4, decompressor, NullLogger.Instance));
            Assert.False(File.Exists(path));
            Assert.Equal(invalid, File.ReadAllBytes(path + ".corrupt"));

            File.WriteAllBytes(path, ReplayShared.SerializeReplay(Header(1), [CompactFrame()]));
            var loaded = ReplayShared.LoadReplayFromPath(path, 2, 3, 4, decompressor, NullLogger.Instance);
            Assert.True(loaded.HasValue);
            AssertFrame(loaded.Value, CompactFrame(), 2);
        }
        finally
        {
            File.Delete(path);
            File.Delete(path + ".corrupt");
        }
    }

    private sealed class DelayedRecordingStream : MemoryStream
    {
        public int LargestWrite { get; private set; }

        public override async ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            // Force the encoder to preserve its borrowed block across a genuinely asynchronous write.
            await Task.Yield();
            cancellationToken.ThrowIfCancellationRequested();
            LargestWrite = Math.Max(LargestWrite, buffer.Length);
            Write(buffer.Span);
        }
    }

    private static ReplayFrameData WithComponent(ReplayFrameData frame, int component, float value)
        => component switch
        {
            0 => frame with { Origin = new Vector(value, frame.Origin.Y, frame.Origin.Z) },
            1 => frame with { Origin = new Vector(frame.Origin.X, value, frame.Origin.Z) },
            2 => frame with { Origin = new Vector(frame.Origin.X, frame.Origin.Y, value) },
            3 => frame with { Velocity = new Vector(value, frame.Velocity.Y, frame.Velocity.Z) },
            4 => frame with { Velocity = new Vector(frame.Velocity.X, value, frame.Velocity.Z) },
            5 => frame with { Velocity = new Vector(frame.Velocity.X, frame.Velocity.Y, value) },
            6 => frame with { Angles = new Vector2D(value, frame.Angles.Y) },
            7 => frame with { Angles = new Vector2D(frame.Angles.X, value) },
            _ => throw new ArgumentOutOfRangeException(nameof(component)),
        };

    private static float GetComponent(ReplayFrameData frame, int component)
        => component switch
        {
            0 => frame.Origin.X, 1 => frame.Origin.Y, 2 => frame.Origin.Z,
            3 => frame.Velocity.X, 4 => frame.Velocity.Y, 5 => frame.Velocity.Z,
            6 => frame.Angles.X, 7 => frame.Angles.Y,
            _ => throw new ArgumentOutOfRangeException(nameof(component)),
        };

    private static ReplayLoadResult Decode(byte[] bytes)
    {
        var loaded = ReplayShared.DeserializeReplay(bytes, 2, 3, 4, NullLogger.Instance);
        Assert.True(loaded.HasValue);
        return loaded.Value;
    }

    private static void AssertFrame(ReplayLoadResult loaded, ReplayFrameData expected, int version)
    {
        Assert.Equal(2, loaded.Style);
        Assert.Equal(3, loaded.Track);
        Assert.Equal(4, loaded.Stage);
        Assert.Equal(version, loaded.Content.Header.Version);
        Assert.Equal(expected, Assert.Single(loaded.Content.Frames));
    }

    private static ReplayFrameData CompactFrame()
        => LegacyFrame() with
        {
            PressedButtons = (UserCommandButtons)0xFFFFFFFFUL,
            ChangedButtons = (UserCommandButtons)0x90000001UL,
            ScrollButtons = (UserCommandButtons)0x48000002UL,
        };

    private static ReplayFrameData CompactFrameWithHighButtons()
        => CompactFrame() with
        {
            PressedButtons = (UserCommandButtons)ulong.MaxValue,
            ChangedButtons = (UserCommandButtons)0xFEDCBA9890000001UL,
            ScrollButtons = (UserCommandButtons)0xFFFFFFFF48000002UL,
        };

    private static ReplayFrameData V1FallbackFrame()
        => LegacyFrame() with { Angles = new Vector2D(2000f, -179.25f) };

    private static ReplayFrameData LowButtons(ReplayFrameData frame)
        => frame with
        {
            PressedButtons = (UserCommandButtons)((ulong)frame.PressedButtons & 0xFFFFFFFFUL),
            ChangedButtons = (UserCommandButtons)((ulong)frame.ChangedButtons & 0xFFFFFFFFUL),
            ScrollButtons = (UserCommandButtons)((ulong)frame.ScrollButtons & 0xFFFFFFFFUL),
        };

    private static ReplayFrameData LegacyFrame()
        => new()
        {
            Origin = new Vector(1.25f, -2.5f, 3.75f),
            Angles = new Vector2D(12.5f, -179.25f),
            PressedButtons = (UserCommandButtons)ulong.MaxValue,
            ChangedButtons = (UserCommandButtons)0x8000000900000001UL,
            ScrollButtons = (UserCommandButtons)0x4000000480000002UL,
            MoveType = (MoveType)8,
            Velocity = new Vector(-128.125f, 64.5f, 0.03125f),
        };

    private static ReplayFileHeader Header(int frameCount)
        => new()
        {
            SteamId = 76561198000000001,
            TotalFrames = frameCount,
            Time = 1.25f,
            PlayerName = "legacy-fixture",
        };

    private static byte[] Payload(byte[] bytes)
        => bytes[(Array.IndexOf(bytes, (byte)ReplayShared.HeaderFrameSeparator) + 1)..];

    private static byte[] Wrap<T>(T header, byte[] payload)
    {
        using var stream = new MemoryStream();
        JsonSerializer.Serialize(stream, header);
        stream.WriteByte((byte)ReplayShared.HeaderFrameSeparator);
        stream.Write(payload);
        return stream.ToArray();
    }

    private static string TempPath() => Path.Combine(Path.GetTempPath(), $"timer-replay-format-{Guid.NewGuid():N}.replay");
}
